import Foundation

/// The emoji in the space icon picker, in Unicode's order and grouped like the category bar of
/// Arc's picker (EmojiCatalog+Data.swift is generated by scripts/make-emoji-catalog.py). Shared by
/// the Mac's SpaceIconPicker and the Windows picker.
public enum EmojiCatalog {
    public struct Entry: Hashable, Sendable {
        public let emoji: String
        public let name: String

        public init(emoji: String, name: String) {
            self.emoji = emoji
            self.name = name
        }
    }

    public struct Category: Identifiable, Sendable {
        public let id: String
        /// The glyph in the picker's bottom bar (an SF Symbols name).
        public let symbol: String
        public let entries: [Entry]
    }

    private static let symbols = [
        "smileys": "face.smiling", "nature": "sun.max", "food": "mug", "activities": "rosette",
        "travel": "box.truck", "objects": "gift", "symbols": "heart", "flags": "flag",
    ]

    /// Emoji 15.0 and older (the catalog's cut-off) all draw on macOS 14, Cra's oldest, and on
    /// Windows 11's Segoe UI Emoji.
    public static let categories: [Category] = data.map { key, text in
        let entries = text.split(separator: "\n").compactMap { line -> Entry? in
            guard let space = line.firstIndex(of: " ") else { return nil }
            return Entry(emoji: String(line[..<space]), name: String(line[line.index(after: space)...]))
        }
        return Category(id: key, symbol: symbols[key] ?? "circle", entries: entries)
    }

    public static let all: [Entry] = categories.flatMap(\.entries)

    /// Entries whose name holds every word of `query`; none for an empty query.
    public static func search(_ query: String) -> [Entry] {
        let words = query.lowercased().split(separator: " ")
        guard !words.isEmpty else { return [] }
        return all.filter { e in words.allSatisfy { e.name.contains($0) } }
    }

    /// The picker's grid is `columns` wide and opens with the current emoji's row at the top:
    /// the first emoji of that row, nil when `emoji` isn't in the catalog.
    public static func rowStart(of emoji: String, columns: Int = 8) -> String? {
        guard columns > 0, let i = all.firstIndex(where: { $0.emoji == emoji }) else { return nil }
        return all[i - i % columns].emoji
    }
}
